# === PyGen 注入：HTTP/SSL 韧性层（通用） ===
# 说明：
# 1) 优先保持 verify=True；如确需临时绕过（不推荐），可设置环境变量 PYGEN_INSECURE_SSL=1
# 2) 默认遇到 418/403/429 仅做一次"预热 cookie + 浏览器化 headers"的重试
# 3) 若仍被拦截且本机已安装 Playwright，会自动尝试一次 request-context 兜底
#    如需禁用：设置 PYGEN_DISABLE_PLAYWRIGHT_FALLBACK=1
import os as _pygen_os
import ssl as _pygen_ssl
import urllib.parse as _pygen_urlparse

try:
    # truststore 会让 Python/requests 使用系统证书库（Windows/macOS/Linux），更贴近浏览器行为
    import truststore as _pygen_truststore  # type: ignore
    _pygen_truststore.inject_into_ssl()
except Exception:
    _pygen_truststore = None  # noqa: F401

try:
    import requests as _pygen_requests
    from requests.structures import CaseInsensitiveDict as _pygen_CaseInsensitiveDict
except Exception:
    _pygen_requests = None  # noqa: F401

_PYGEN_DEFAULT_UA = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
    "AppleWebKit/537.36 (KHTML, like Gecko) "
    "Chrome/122.0 Safari/537.36"
)

def _pygen_origin(url: str) -> str:
    try:
        p = _pygen_urlparse.urlsplit(url)
        return f"{p.scheme}://{p.netloc}"
    except Exception:
        return ""

def _pygen_merge_headers(h: dict | None) -> dict:
    base = {
        "User-Agent": _PYGEN_DEFAULT_UA,
        "Accept": "application/json,text/plain,*/*",
        "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
        "Connection": "keep-alive",
    }
    if h:
        for k, v in h.items():
            if v is not None:
                base[k] = v
    return base

def _pygen_make_response(status: int, url: str, headers: dict, body: bytes):
    r = _pygen_requests.Response()
    r.status_code = status
    r.url = url
    r.headers = _pygen_CaseInsensitiveDict(headers or {})
    r._content = body or b""
    return r

def _pygen_playwright_fetch(method: str, url: str, headers: dict, data=None, json=None, timeout: int = 30):
    """
    兜底：使用 Playwright 的 request context（更像浏览器/更容易过 WAF）。
    仅当已安装 playwright 且未设置 PYGEN_DISABLE_PLAYWRIGHT_FALLBACK=1 时启用。
    """
    if _pygen_os.getenv("PYGEN_DISABLE_PLAYWRIGHT_FALLBACK") == "1":
        return None
    try:
        from playwright.sync_api import sync_playwright  # type: ignore
    except Exception:
        return None

    with sync_playwright() as p:
        ctx = p.request.new_context(ignore_https_errors=_pygen_os.getenv("PYGEN_INSECURE_SSL") == "1",
                                    extra_http_headers=headers)
        try:
            resp = ctx.fetch(url, method=method.upper(), data=data, json=json, timeout=timeout * 1000)
            body = resp.body()
            return _pygen_make_response(resp.status, url, dict(resp.headers), body)
        finally:
            ctx.dispose()

def _pygen_install_requests_patch():
    if _pygen_requests is None:
        return
    _orig = _pygen_requests.sessions.Session.request

    def _patched(self, method, url, **kwargs):
        # 默认超时，避免脚本卡死
        kwargs.setdefault("timeout", 30)

        # 证书校验策略：默认开启；仅在用户明确设置时关闭
        if _pygen_os.getenv("PYGEN_INSECURE_SSL") == "1":
            kwargs["verify"] = False

        # 合并"更像浏览器"的 headers（很多站会对 UA/Accept 做拦截）
        headers = _pygen_merge_headers(kwargs.get("headers"))
        kwargs["headers"] = headers

        # 首次请求
        try:
            resp = _orig(self, method, url, **kwargs)
        except Exception as e:
            # 若是 SSL 校验错误：truststore 已注入则直接抛出；否则给出更友好的提示
            msg = str(e)
            if "CERTIFICATE_VERIFY_FAILED" in msg or "certificate verify failed" in msg:
                # 若 playwright 可用，尝试用 request-context 做一次兜底（有些环境下系统信任链更完整）
                try:
                    pw_resp = _pygen_playwright_fetch(method, url, headers=headers,
                                                      data=kwargs.get("data"),
                                                      json=kwargs.get("json"),
                                                      timeout=int(kwargs.get("timeout") or 30))
                    if pw_resp is not None:
                        return pw_resp
                except Exception:
                    pass
                raise
            raise

        # WAF/反爬：做一次轻量重试（预热 cookie + 再请求）
        if resp is not None and getattr(resp, "status_code", 0) in (418, 403, 429):
            try:
                origin = _pygen_origin(url)
                if origin:
                    # 预热：访问首页拿 cookie
                    _ = _orig(self, "GET", origin + "/", headers=headers, timeout=15, verify=kwargs.get("verify", True))
                resp2 = _orig(self, method, url, **kwargs)
                if resp2 is not None and getattr(resp2, "status_code", 0) not in (418, 403, 429):
                    return resp2
                # 若仍被拦截，且 playwright 可用，则再尝试一次（自动兜底）
                pw_resp = _pygen_playwright_fetch(method, url, headers=headers,
                                                  data=kwargs.get("data"),
                                                  json=kwargs.get("json"),
                                                  timeout=int(kwargs.get("timeout") or 30))
                if pw_resp is not None:
                    return pw_resp
            except Exception:
                # 兜底失败则返回原始响应，交由上层处理
                return resp

        return resp

    _pygen_requests.sessions.Session.request = _patched

_pygen_install_requests_patch()
# === PyGen 注入结束 ===
import requests
from bs4 import BeautifulSoup
import json
import os
import time
import random
from urllib.parse import urljoin
from datetime import datetime
import re

# ================= 配置区域 =================
TARGET_URL = "https://www.cityam.com/news/"
OUTPUT_DIR = "output"  # 使用相对路径，增强移植性
MAX_ARTICLES = 5  # 限制爬取数量

# 请求头配置
HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.9",
    "Referer": "https://www.cityam.com/",
    "Connection": "keep-alive",
    "Upgrade-Insecure-Requests": "1",
    "Sec-Fetch-Dest": "document",
    "Sec-Fetch-Mode": "navigate",
    "Sec-Fetch-Site": "same-origin",
    "Sec-Fetch-User": "?1",
}

def get_random_delay():
    """生成随机延迟，避免请求过快"""
    return random.uniform(1.5, 3.5)

def clean_html_content(html_content, base_url):
    """
    清洗HTML内容：
    1. 将相对路径转换为绝对路径
    2. 移除无用的标签
    """
    if not html_content:
        return ""
    try:
        soup = BeautifulSoup(html_content, 'html.parser')

        # 修复图片链接
        for img in soup.find_all('img'):
            if img.get('src'):
                img['src'] = urljoin(base_url, img['src'])
            # 移除 srcset 属性，避免混淆
            if img.get('srcset'):
                del img['srcset']

        # 修复超链接
        for a in soup.find_all('a'):
            if a.get('href'):
                a['href'] = urljoin(base_url, a['href'])

        # 移除脚本和样式
        for script in soup(["script", "style", "iframe", "noscript"]):
            script.decompose()

        # 移除特定的干扰元素 (根据用户策略)
        # 增加对 cookie banner 的移除，防止内容污染
        remove_selectors = [
            'header', 'footer', 'aside', 
            '.notice-header', '.newsletter-auto-inject', '.share-tools',
            '#onetrust-consent-sdk', '#onetrust-banner-sdk', '.optanon-alert-box-wrapper'
        ]
        for selector in remove_selectors:
            for tag in soup.select(selector):
                tag.decompose()

        return str(soup)
    except Exception as e:
        print(f"[WARN] 内容清洗出错: {e}")
        return html_content

def extract_date(soup):
    """
    尝试多种方式提取发布日期
    """
    date_str = ""

    # 策略1: 用户指定的选择器
    time_tag = soup.select_one('time.date-time__time')
    if time_tag:
        if time_tag.get('datetime'):
            date_str = time_tag.get('datetime')
        else:
            date_str = time_tag.get_text(strip=True)

    # 策略2: Meta 标签 (通常更标准)
    if not date_str:
        meta_date = soup.find('meta', property='article:published_time') or \
                    soup.find('meta', property='og:article:published_time') or \
                    soup.find('meta', itemprop='datePublished')
        if meta_date:
            date_str = meta_date.get('content')

    # 策略3: JSON-LD
    if not date_str:
        try:
            scripts = soup.find_all('script', type='application/ld+json')
            for script in scripts:
                if 'datePublished' in script.string:
                    data = json.loads(script.string)
                    if isinstance(data, dict):
                        date_str = data.get('datePublished', '')
                    elif isinstance(data, list):
                        for item in data:
                            if 'datePublished' in item:
                                date_str = item.get('datePublished', '')
                                break
                    if date_str: break
        except:
            pass

    # 格式化日期为 YYYY-MM-DD
    if date_str:
        try:
            # 处理 ISO 格式 2024-02-19T12:00:00+00:00
            dt = None
            if 'T' in date_str:
                dt = datetime.fromisoformat(date_str.replace('Z', '+00:00'))
            else:
                # 尝试常见格式
                for fmt in ["%Y-%m-%d", "%d %B %Y", "%B %d, %Y"]:
                    try:
                        dt = datetime.strptime(date_str, fmt)
                        break
                    except:
                        continue

            if dt:
                return dt.strftime("%Y-%m-%d")
        except Exception as e:
            print(f"[WARN] 日期格式化失败: {date_str} - {e}")
            # 如果解析失败，返回原始字符串的前10位（如果是YYYY-MM-DD格式的话）
            if re.match(r'\d{4}-\d{2}-\d{2}', date_str):
                return date_str[:10]

    return datetime.now().strftime("%Y-%m-%d") # 兜底：当前日期

def crawl_detail_page(url):
    """爬取详情页内容"""
    try:
        print(f"正在爬取详情页: {url}")
        time.sleep(get_random_delay())

        response = requests.get(url, headers=HEADERS, timeout=15)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')

        # 提取日期
        pub_date = extract_date(soup)

        # 提取正文 - 增强版选择器策略
        article_body = None
        candidate_selectors = [
            'article.content-container.content-container__single', # 原有选择器
            'div.post-content',      # 常见 WordPress 内容容器
            'div.entry-content',     # 常见 WordPress 内容容器
            'div.article-body',      # 常见新闻网站容器
            'main article',          # 语义化标签
            'article'                # 最泛化的标签
        ]

        for selector in candidate_selectors:
            element = soup.select_one(selector)
            if element:
                # 简单验证：内容长度是否足够（避免选中空容器）
                if len(element.get_text(strip=True)) > 50:
                    article_body = element
                    break

        content_html = ""
        summary = ""

        if article_body:
            # 提取纯文本用于摘要
            paragraphs = article_body.find_all('p')
            text_content = [p.get_text(strip=True) for p in paragraphs if p.get_text(strip=True)]

            # 生成摘要 (前3段或前500字)
            summary_text = " ".join(text_content[:3])
            if len(summary_text) > 500:
                summary = summary_text[:497] + "..."
            else:
                summary = summary_text

            # 获取清洗后的 HTML
            # 移除不需要的元素后再获取 HTML
            for tag in article_body.select('.newsletter-auto-inject, .share-tools, aside'):
                tag.decompose()

            content_html = clean_html_content(str(article_body), url)
        else:
            print(f"[WARN] 未找到正文内容: {url}")

        return {
            "date": pub_date,
            "content": content_html,
            "summary": summary
        }

    except Exception as e:
        print(f"[ERROR] 详情页爬取失败 {url}: {e}")
        return None

def crawl_news_list():
    """爬取新闻列表页"""
    articles = []

    try:
        print(f"正在访问列表页: {TARGET_URL}")
        response = requests.get(TARGET_URL, headers=HEADERS, timeout=15)
        response.raise_for_status()

        soup = BeautifulSoup(response.text, 'html.parser')

        # 列表项选择器 (增加兜底)
        items = soup.select('.content-listing__content-item')
        if not items:
            items = soup.select('article')

        print(f"找到 {len(items)} 个新闻项")

        count = 0
        for item in items:
            if count >= MAX_ARTICLES:
                break

            # 提取标题和链接
            title_tag = item.select_one('.card__title a')
            if not title_tag:
                # 尝试备选选择器
                title_tag = item.select_one('h2 a') or item.select_one('h3 a')

            if not title_tag:
                continue

            title = title_tag.get_text(strip=True)
            link = title_tag.get('href')

            if not link:
                continue

            # 补全链接
            full_link = urljoin(TARGET_URL, link)

            # 提取作者 (如果有)
            author = "City AM" # 默认

            print(f"处理第 {count + 1} 条: {title}")

            # 进入详情页获取更多信息
            detail_data = crawl_detail_page(full_link)

            if detail_data:
                article = {
                    "id": str(count + 1),
                    "title": title,
                    "name": title, # 增加 name 字段以满足 Schema 检查要求
                    "date": detail_data.get('date', ''),
                    "author": author,
                    "source": "City AM",
                    "sourceUrl": full_link,
                    "summary": detail_data.get('summary', ''),
                    "content": detail_data.get('content', '')
                }
                articles.append(article)
                count += 1

    except Exception as e:
        print(f"[ERROR] 列表页爬取失败: {e}")

    return articles

def save_results(articles, output_dir):
    """保存结果为 JSON"""
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"cityam_news_{timestamp}.json"
    filepath = os.path.join(output_dir, filename)

    result = {
        "total": len(articles),
        "crawlTime": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "articles": articles
    }

    try:
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(result, f, ensure_ascii=False, indent=2)
        print(f"成功保存 {len(articles)} 条数据到: {filepath}")
    except Exception as e:
        print(f"[ERROR] 保存文件失败: {e}")

def main():
    print("=== 开始爬取 City AM 新闻 ===")
    articles = crawl_news_list()

    if articles:
        save_results(articles, OUTPUT_DIR)
    else:
        print("未获取到任何新闻数据。")
    print("=== 爬取任务结束 ===")

if __name__ == "__main__":
    main()
